// Wokwi 模拟项目（Arduino Uno）——电路见 diagram.json：数字 13 引脚经 330Ω 电阻接红色 LED。
// 程序让 LED 闪烁，并在串口打印状态（wokwi_run 可捕获这些输出验证行为）。
void setup() {
  pinMode(13, OUTPUT);
  Serial.begin(9600);
  Serial.println("Wokwi simulation started!");
}

void loop() {
  digitalWrite(13, HIGH);
  Serial.println("LED ON");
  delay(500);
  digitalWrite(13, LOW);
  Serial.println("LED OFF");
  delay(500);
}
